type ExternalCommand struct {
	// Err is the error returned, if non-nil.
	Err error

	// Cmd contains the command path and arguments.
	Cmd string

	// Out is written to stdout if non-empty.
	Out string

	// Code is returned as the exit code if non-zero.
	Code osutil.ExitCode
}

func keyCommand(path string, args []string) (k string) {
	if len(args) == 0 {
		return path
	}

	return path + " " + strings.Join(args, " ")
}

func parseCommand(s string) (path string, args []string) {
	f := strings.Fields(s)
	if len(f) == 0 {
		return "", nil
	}

	return f[0], f[1:]
}

func NewMultipleCommandConstructor(cmds ...ExternalCommand) (cs executil.CommandConstructor) {
	table := make(map[string]ExternalCommand, len(cmds))
	for _, ec := range cmds {
		p, a := parseCommand(ec.Cmd)
		table[keyCommand(p, a)] = ec
	}

	onNew := func(_ context.Context, conf *executil.CommandConfig) (c executil.Command, err error) {
		ec := table[keyCommand(conf.Path, conf.Args)]

		cmd := fakeexec.NewCommand()
		cmd.OnStart = func(_ context.Context) (err error) {
			if ec.Out != "" {
				_, _ = conf.Stdout.Write([]byte(ec.Out))
			}

			return nil
		}

		cmd.OnWait = func(_ context.Context) (err error) {
			if ec.Err != nil {
				return ec.Err
			}

			if ec.Code != 0 {
				return newExitErr(ec.Code)
			}

			return nil
		}

		return cmd, nil
	}

	return &fakeexec.CommandConstructor{OnNew: onNew}
}

func NewCommandConstructor(
	_ string,
	code osutil.ExitCode,
	stdout string,
	cmdErr error,
) (cs executil.CommandConstructor) {
	onNew := func(_ context.Context, conf *executil.CommandConfig) (c executil.Command, err error) {
		cmd := fakeexec.NewCommand()
		cmd.OnStart = func(_ context.Context) (err error) {
			if conf.Stdout != nil {
				_, _ = conf.Stdout.Write([]byte(stdout))
			}

			return nil
		}

		cmd.OnWait = func(_ context.Context) (err error) {
			if cmdErr != nil {
				return cmdErr
			}

			if code != 0 {
				return newExitErr(code)
			}

			return nil
		}

		return cmd, nil
	}

	return &fakeexec.CommandConstructor{OnNew: onNew}
}

func (uc UniqChecker[T]) Validate() (err error) {
	var dup []T
	for elem, num := range uc {
		if num > 1 {
			dup = append(dup, elem)
		}
	}

	if len(dup) == 0 {
		return nil
	}

	slices.Sort(dup)

	return fmt.Errorf("duplicated values: %v", dup)
}

func (nb NullBool) String() (s string) {
	switch nb {
	case NBNull:
		return "null"
	case NBTrue:
		return "true"
	case NBFalse:
		return "false"
	}

	return fmt.Sprintf("!invalid NullBool %d", uint8(nb))
}

func BoolToNullBool(cond bool) (nb NullBool) {
	return NBFalse - mathutil.BoolToNumber[NullBool](cond)
}

func (nb NullBool) MarshalJSON() (b []byte, err error) {
	return []byte(nb.String()), nil
}

func (nb *NullBool) UnmarshalJSON(b []byte) (err error) {
	if len(b) == 0 || bytes.Equal(b, []byte("null")) {
		*nb = NBNull
	} else if bytes.Equal(b, []byte("true")) {
		*nb = NBTrue
	} else if bytes.Equal(b, []byte("false")) {
		*nb = NBFalse
	} else {
		return fmt.Errorf("unmarshalling json data into aghalg.NullBool: bad value %q", b)
	}

	return nil
}

func (m *SortedMap[K, V]) Set(key K, val V) {
	m.vals[key] = val

	i, has := slices.BinarySearchFunc(m.keys, key, m.cmp)
	if has {
		m.keys[i] = key
	} else {
		m.keys = slices.Insert(m.keys, i, key)
	}
}

func (m *SortedMap[K, V]) Get(key K) (val V, ok bool) {
	if m == nil {
		var zero V

		return zero, false
	}

	val, ok = m.vals[key]

	return val, ok
}

func (m *SortedMap[K, V]) Del(key K) {
	if m == nil {
		return
	}

	if _, has := m.vals[key]; !has {
		return
	}

	delete(m.vals, key)
	i, _ := slices.BinarySearchFunc(m.keys, key, m.cmp)
	m.keys = slices.Delete(m.keys, i, i+1)
}

func (m *SortedMap[K, V]) Range(cb func(K, V) (cont bool)) {
	if m == nil {
		return
	}

	for _, k := range m.keys {
		if !cb(k, m.vals[k]) {
			return
		}
	}
}

