// pages.
func (mw *authMiddlewareDefault) handlePublicAccess(
	w http.ResponseWriter,
	r *http.Request,
	h http.Handler,
	path string,
) (ok bool) {
	if isPublicResource(path) || mw.isDoHRoute(r) {
		h.ServeHTTP(w, r)

		return true
	}

	if path == "/" || path == "/index.html" {
		http.Redirect(w, r, "login.html", http.StatusFound)

		return true
	}

	return false
